proc placeRegion(p: Place): string =
  let t = p.region.strip
  if t.len > 0: t else: "Unsorted"

proc jstr(n: JsonNode, key: string): string =
  let c = n{key}
  if c == nil or c.kind != JString: "" else: c.getStr

proc jbool(n: JsonNode, key: string): bool =
  let c = n{key}
  if c != nil and c.kind == JBool: c.getBool else: false

proc jint(n: JsonNode, key: string): int =
  let c = n{key}
  if c != nil and c.kind == JInt: int(c.getInt) else: 0

