proc parseCatalog*(text: string): seq[Place] =
  result = @[]
  for line in text.splitLines:
    let t = line.strip
    if t.len == 0 or t[0] != '{': continue
    try:
      let n = parseJson(t)
      let p = Place(
        name: jstr(n, "name"),
        region: jstr(n, "region"),
        kind: jstr(n, "kind"),
        notes: jstr(n, "notes"),
        visited: jbool(n, "visited"),
        interest: jint(n, "interest"))
      if p.name.len > 0: result.add(p)
    except CatchableError:
      discard

proc catalogText*(rows: seq[Place]): string =
  result = ""
  for p in rows:
    if result.len > 0: result.add('\n')
    result.add($ %*{
      "name": p.name,
      "region": p.region,
      "kind": p.kind,
      "visited": p.visited,
      "interest": p.interest,
      "notes": p.notes
    })
  if result.len > 0: result.add('\n')

proc writeCatalog(path: string): string =
  try:
    writeFile(path, catalogText(places))
  except CatchableError as e:
    result = e.msg

proc matchesPlace*(p: Place, region, query, kind: string, visitedOnly: bool): bool =
  if region.len > 0 and placeRegion(p) != region: return false
  if visitedOnly and not p.visited: return false
  if kind.len > 0 and kind != "All" and p.kind != kind: return false
  if query.len > 0:
    let hay = (p.name & "\n" & p.region & "\n" & p.kind & "\n" & p.notes).toLowerAscii
    if query.toLowerAscii notin hay: return false
  true

proc freshName(): string =
  var n = 1
  result = "New place"
  while true:
    var taken = false
    for p in places:
      if p.name == result: taken = true
    if not taken: return
    inc n
    result = "New place " & $n

proc noteLine(self: TAtlas, text: string) =
  let stamp = format(now(), "HH:mm:ss")
  var body = self.JournalMemo.text
  if body.len > 0 and not body.endsWith("\n"): body.add('\n')
  body.add(stamp & "  " & text)
  self.JournalMemo.text = body
  self.JournalMemo.scrollToEnd()

proc selectedPlace(self: TAtlas): Place =
  let i = self.PlaceList.itemIndex
  if i >= 0 and i < shown.len: shown[i] else: nil

proc fillRegionCombo(self: TAtlas) =
  var names: seq[string] = @[]
  for p in places:
    let r = placeRegion(p)
    if r notin names: names.add(r)
  if names != self.RegionCombo.items:
    self.RegionCombo.items = names

proc showPlace(self: TAtlas, p: Place) =
  let prev = filling
  filling = true
  fillRegionCombo(self)
  self.NameEdit.text = p.name
  var kindIdx = 0
  for i, n in self.KindCombo.items:
    if n == p.kind: kindIdx = i
  self.KindCombo.itemIndex = kindIdx
  let region = placeRegion(p)
  var regionIdx = -1
  for i, n in self.RegionCombo.items:
    if n == region: regionIdx = i
  if regionIdx >= 0:
    self.RegionCombo.itemIndex = regionIdx
  else:
    self.RegionCombo.items = self.RegionCombo.items & @[region]
    self.RegionCombo.itemIndex = self.RegionCombo.items.high
  self.VisitedCheck.checked = p.visited
  self.InterestBar.position = p.interest
  self.InterestProgress.position = p.interest
  self.NotesMemo.text = p.notes
  filling = prev

proc clearFields(self: TAtlas) =
  let prev = filling
  filling = true
  self.NameEdit.text = ""
  self.KindCombo.itemIndex = -1
  self.RegionCombo.itemIndex = -1
  self.VisitedCheck.checked = false
  self.InterestBar.position = 0
  self.InterestProgress.position = 0
  self.NotesMemo.text = ""
  filling = prev

proc statusLine(self: TAtlas) =
  var seen = 0
  for p in places:
    if p.visited: inc seen
  var where = "all regions"
  if regionPick.len > 0: where = regionPick
  self.StatusBar.simpleText = $shown.len & " shown    " & $places.len & " places    " &
    $seen & " visited    " & where & "    " & format(now(), "HH:mm:ss")

proc rebuildTree(self: TAtlas) =
  self.RegionTree.clear()
  discard self.RegionTree.addNode(nil, "All regions")
  var seen: seq[string] = @[]
  for p in places:
    let r = placeRegion(p)
    if r notin seen: seen.add(r)
  for r in seen:
    let parent = self.RegionTree.addNode(nil, r)
    for p in places:
      if placeRegion(p) == r:
        let name = if p.name.strip.len > 0: p.name else: "(unnamed)"
        discard self.RegionTree.addNode(parent, name)
  self.RegionTree.expandAll()

proc refreshList(self: TAtlas, prefer: Place = nil) =
  var keep = prefer
  if keep == nil and self.PlaceList.itemIndex >= 0 and self.PlaceList.itemIndex < shown.len:
    keep = shown[self.PlaceList.itemIndex]
  let query = self.FilterEdit.text
  let kind = self.KindFilter.text
  let only = self.VisitedOnly.checked
  shown = @[]
  var names: seq[string] = @[]
  for p in places:
    if matchesPlace(p, regionPick, query, kind, only):
      shown.add(p)
      names.add(if p.name.strip.len > 0: p.name else: "(unnamed)")
  var idx = -1
  if keep != nil:
    for i, p in shown:
      if p == keep: idx = i
  if idx < 0 and shown.len > 0: idx = 0
  let prev = filling
  filling = true
  self.PlaceList.items = names
  self.PlaceList.itemIndex = idx
  filling = prev
  if idx >= 0: showPlace(self, shown[idx])
  else: clearFields(self)
  self.statusLine()

proc loadPath(self: TAtlas, path: string) =
  catalogPath = path
  var fromFile = false
  if fileExists(path):
    try:
      places = parseCatalog(readFile(path))
      fromFile = places.len > 0
    except CatchableError as e:
      places = @[]
      self.noteLine("Could not read " & path & " (" & e.msg & ")")
  if places.len == 0:
    places = seedPlaces()
    fromFile = false
  regionPick = ""
  fillRegionCombo(self)
  rebuildTree(self)
  refreshList(self)
  if fromFile: self.noteLine("Opened " & path & " (" & $places.len & ")")
  else: self.noteLine("Using the built-in catalog (" & $places.len & ")")

proc RegionTreeSelect(self: TAtlas, sender: TObject, node: TTreeNode) =
  if filling or node == nil: return
  let label = node.text
  if label == "All regions":
    regionPick = ""
    refreshList(self)
    return
  for p in places:
    if placeRegion(p) == label:
      regionPick = label
      refreshList(self)
      return
  for p in places:
    let name = if p.name.strip.len > 0: p.name else: "(unnamed)"
    if name == label:
      regionPick = placeRegion(p)
      refreshList(self, p)
      return
