proc AtlasCreate*(self: TAtlas; sender: TObject) =
  # TTreeView stores its selection proc on the control. It is not a published event.
  self.RegionTree.onSelect = proc(sender: TObject, node: TTreeNode) =
    self.RegionTreeSelect(sender, node)
  self.JournalMemo.monospace = true
  loadPath(self, getAppDir() / "atlas.catalog")

proc AtlasClose*(self: TAtlas; sender: TObject; action: var TCloseAction) =
  if catalogPath.len > 0: discard writeCatalog(catalogPath)

proc FilterEditChange*(self: TAtlas; sender: TObject) =
  if filling: return
  refreshList(self)

proc KindFilterChange*(self: TAtlas; sender: TObject) =
  if filling: return
  refreshList(self)

proc VisitedOnlyClick*(self: TAtlas; sender: TObject) =
  if filling: return
  refreshList(self)

proc PlaceListClick*(self: TAtlas; sender: TObject) =
  if filling: return
  let p = selectedPlace(self)
  if p != nil: showPlace(self, p)

proc NameEditChange*(self: TAtlas; sender: TObject) =
  if filling: return
  let p = selectedPlace(self)
  if p == nil: return
  p.name = self.NameEdit.text
  let idx = self.PlaceList.itemIndex
  if idx >= 0 and idx < shown.len:
    let prev = filling
    filling = true
    var names = self.PlaceList.items
    if idx < names.len:
      names[idx] = if p.name.strip.len > 0: p.name else: "(unnamed)"
      self.PlaceList.items = names
      self.PlaceList.itemIndex = idx
    filling = prev
  rebuildTree(self)

proc KindComboChange*(self: TAtlas; sender: TObject) =
  if filling: return
  let p = selectedPlace(self)
  if p == nil or self.KindCombo.text.len == 0: return
  p.kind = self.KindCombo.text
  self.noteLine(p.name & " set to " & p.kind)
  refreshList(self, p)

proc VisitedCheckClick*(self: TAtlas; sender: TObject) =
  if filling: return
  let p = selectedPlace(self)
  if p == nil: return
  p.visited = self.VisitedCheck.checked
  if p.visited: self.noteLine(p.name & " marked visited")
  else: self.noteLine(p.name & " marked not visited")
  refreshList(self, p)

proc RegionComboChange*(self: TAtlas; sender: TObject) =
  if filling: return
  let p = selectedPlace(self)
  if p == nil: return
  p.region = self.RegionCombo.text
  rebuildTree(self)
  if self.RegionCombo.itemIndex >= 0:
    regionPick = placeRegion(p)
    refreshList(self, p)
  else:
    self.statusLine()

proc InterestBarChange*(self: TAtlas; sender: TObject) =
  if filling: return
  let p = selectedPlace(self)
  if p == nil: return
  p.interest = self.InterestBar.position
  self.InterestProgress.position = p.interest

proc NotesMemoChange*(self: TAtlas; sender: TObject) =
  if filling: return
  let p = selectedPlace(self)
  if p == nil: return
  p.notes = self.NotesMemo.text

proc OpenItemClick*(self: TAtlas; sender: TObject) =
  if catalogPath.len > 0:
    let err = writeCatalog(catalogPath)
    if err.len > 0:
      discard messageDlg("Could not save the current catalog. " & err, mtError, {mbOK})
      return
  self.OpenDialog.fileName = catalogPath
  if not self.OpenDialog.execute(): return
  loadPath(self, self.OpenDialog.fileName)

proc SaveItemClick*(self: TAtlas; sender: TObject) =
  self.SaveDialog.fileName = catalogPath
  if not self.SaveDialog.execute(): return
  var path = self.SaveDialog.fileName
  if not path.toLowerAscii.endsWith(".catalog"): path.add(".catalog")
  let err = writeCatalog(path)
  if err.len > 0:
    discard messageDlg("Could not save. " & err, mtError, {mbOK})
    return
  catalogPath = path
  self.noteLine("Saved " & path)
  self.statusLine()

proc QuitItemClick*(self: TAtlas; sender: TObject) =
  if catalogPath.len > 0: discard writeCatalog(catalogPath)
  application.terminate()

proc AddItemClick*(self: TAtlas; sender: TObject) =
  var region = regionPick
  if region.len == 0:
    if places.len > 0: region = placeRegion(places[0])
    else: region = "Mediterranean"
  let p = Place(name: freshName(), region: region, kind: "City", notes: "",
    visited: false, interest: 40)
  places.add(p)
  let prev = filling
  filling = true
  self.FilterEdit.text = ""
  self.VisitedOnly.checked = false
  self.KindFilter.itemIndex = 0
  filling = prev
  regionPick = region
  rebuildTree(self)
  refreshList(self, p)
  self.NameEdit.focus()
  self.noteLine("Added " & p.name)

proc RemoveItemClick*(self: TAtlas; sender: TObject) =
  let p = selectedPlace(self)
  if p == nil: return
  if messageDlg("Remove " & p.name & " from the catalog?", mtConfirmation, {mbYes, mbNo}) != mrYes:
    return
  var kept: seq[Place] = @[]
  for q in places:
    if q != p: kept.add(q)
  places = kept
  rebuildTree(self)
  refreshList(self)
  self.noteLine("Removed " & p.name)

proc ClockTimer*(self: TAtlas; sender: TObject) =
  self.statusLine()
